FM_DROP = [("G4", "Spec_Rack!F12"), ("RU", "Spec_Rack!G9")]      # become Derived constants (blue inputs), see INPUT_UPD

def formula_map(base):
    fm = dict(base)
    for step, key in FM_DROP:
        if step_on(step): fm.pop(key, None)
    for step, key, f in FM_ADD:
        if step_on(step): fm[key] = f
    return fm

