def _set_input(ws, cell, val):
    c = ws[cell]
    c.value = val
    if isinstance(val, (int, float)):
        c.font = copy(F_IN); c.fill = PatternFill(fill_type=None)
    elif isinstance(val, str) and val.startswith("="):
        c.font = copy(F_CALC); c.fill = PatternFill(fill_type=None)

def inputs_update(wb):
    """Called after restore() and before gov_all(): numeric inputs (Excel-owned) and Spec_Rack text, each only while at its v5.17 value."""
    log = []
    for step, sh, cell, old, new in INPUT_UPD:
        if not step_on(step): continue
        ws = wb[sh]
        if ws[cell].value == old and type(ws[cell].value) is not bool:
            _set_input(ws, cell, new); log.append(f"{sh}!{cell}: {old!r} -> {new!r} ({step})")
    ws = wb["Spec_Rack"]
    for cell, old, new in TEXT_UPD:
        if ws[cell].value == old:
            ws[cell].value = new; log.append(f"Spec_Rack!{cell}: text updated")
    return log

# ------------------------------------------------------------------ SRC sheets (Excel-owned): field updates with old-value guard
_COL = {k: i + 1 for i, k in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZ")}

def _apply(cell, spec):
    if isinstance(spec, (list, tuple)) and spec and spec[0] == "+":
        txt = spec[1]
        cur = cell.value
        if cur in (None, "", "—"):
            cell.value = txt.lstrip("；｜ ")
        elif txt.lstrip("；｜ ") not in str(cur):         # stripped compare: the first write of an empty cell stores the stripped text
            cell.value = f"{cur}{txt}"
        else: return False
        return True
    old, new = spec
    if cell.value == old:
        cell.value = new; return True
    return False

def src_update(wb):
    n = 0; log = []
    for sid, d in S4.SRC_UPD.items():
        if d["step"] and not step_on(d["step"]): continue
        ws = wb[d["sheet"]]
        row = next((r for r in range(5, ws.max_row + 1) if ws.cell(r, 1).value == sid), None)
        if row is None: log.append(f"{sid}: record not found"); continue
        for col, spec in d["fields"].items():
            if _apply(ws[f"{col}{row}"], spec): n += 1
            else: log.append(f"{sid}!{col}: kept (not at v5.17 value or already applied)")
    return n, log

