# D5 notes appended to the reason column (evidence IDs come from the seed): (sheet, cell, text)
def _d5_notes():
    ev = S4.EV
    return [("Serving", c, f" ｜v5.18 D5（r3 I1）：區間高擴至 68,000 以涵蓋 Copilot 每呼叫提示中位（{ev['ISL']}；Analogy）；基準不動；C23（Luna）不套用") for c in ("D23", "E23")] + \
           [("Workload", c, f" ｜v5.18 r3 I1：區間不改，Copilot 追蹤已讀且已涵蓋（{ev['T']}；單位對應見該列）") for c in ("G5",)] + \
           [("Workload", c, f" ｜v5.18 r3 I1：區間不改，已涵蓋 Copilot 加權命中約 0.90（{ev['CHI']}）；E:G 與 DeepSeek 56.3%（{ev['CHI2']}，C:D）") for c in ("E11",)]

def _append_text(cell, txt):
    cur = cell.value
    if cur in (None, ""): cell.value = txt.lstrip(" ｜"); return True
    if isinstance(cur, str) and txt.lstrip(" ｜") in cur: return False
    if isinstance(cur, str) and cur.startswith("="):
        cell.value = cur + '&"' + txt.replace('"', '""') + '"'; return True
    cell.value = f"{cur}{txt}"; return True

def gov_update(ws):
    """Gov_Map A–P judgement updates (old-value guard) plus the B-method 'O＋L1' segment column (P) and IF-wide supplementary flags."""
    loc = {(ws[f"C{r}"].value, ws[f"D{r}"].value): r for r in range(5, ws.max_row + 1) if ws[f"C{r}"].value}
    n = 0
    for sh, cell, cols in GOV_UPD:
        r = loc.get((sh, cell))
        if r is None: continue
        for col, (old, new) in cols.items():
            c = ws[f"{col}{r}"]
            if c.value == old:
                c.value = new; n += 1
    for sh, cell, txt in _d5_notes():
        r = loc.get((sh, cell))
        if r is not None and _append_text(ws[f"N{r}"], txt): n += 1
    # P: B-method segment ('O＋L1'); Inputs!E5 is 無 per the work order
    for sh, cell, old, new in S4.P_UPD:
        r = loc.get((sh, cell))
        if r is not None and ws[f"P{r}"].value == old:
            ws[f"P{r}"].value = new; n += 1
    # IF-wide segment: supplementary flag in the reason column (not used as the segment basis)
    for key, seg in S4.IF_FLAG.items():
        sh, cell = key.split("|", 1)
        r = loc.get((sh, cell))
        if r is not None and _append_text(ws[f"N{r}"], f" ｜補充旗標（IF 全欄分段，非分段依據）：{seg}"): n += 1
    return n

# ------------------------------------------------------------------ DB_Evidence, Decisions, new SRC records (appended by gov.py loops)
def src_new_records():
    return S4.NEWREC

def evidence_rows():
    rows = [list(r) for r in S4.EVID_MIG4]
    return rows

def decisions_rows():
    return S4.DEC
